from pathlib import Path
p=Path('index.html')
s=p.read_text()
marker='/* Zip live drag fix v4 */'
if marker in s:
    raise SystemExit('already patched')
old="""function zipCellFromPoint(clientX,clientY){const r=zipStage.getBoundingClientRect();if(clientX<r.left||clientX>r.right||clientY<r.top||clientY>r.bottom)return null;const x=Math.max(0,Math.min(zipCols-1,Math.floor((clientX-r.left)/r.width*zipCols))),y=Math.max(0,Math.min(zipRows-1,Math.floor((clientY-r.top)/r.height*zipRows)));return{x,y}}
function zipProcessDrag(x1,y1,x2,y2){const r=zipStage.getBoundingClientRect(),cell=Math.min(r.width/zipCols,r.height/zipRows),dist=Math.hypot(x2-x1,y2-y1),steps=Math.max(1,Math.ceil(dist/Math.max(6,cell*.28)));let last='';for(let i=1;i<=steps;i++){const t=i/steps,c=zipCellFromPoint(x1+(x2-x1)*t,y1+(y2-y1)*t);if(!c)continue;const key=c.x+','+c.y;if(key===last)continue;last=key;zipTryCell(c.x,c.y)}}
const zipStage=$('zipStage');zipStage.addEventListener('pointerdown',e=>{const c=zipCellFromPoint(e.clientX,e.clientY);if(!c)return;e.preventDefault();zipDrag={id:e.pointerId,x:e.clientX,y:e.clientY};try{zipStage.setPointerCapture(e.pointerId)}catch{};zipTryCell(c.x,c.y)});zipStage.addEventListener('pointermove',e=>{if(!zipDrag||zipDrag.id!==e.pointerId)return;e.preventDefault();zipProcessDrag(zipDrag.x,zipDrag.y,e.clientX,e.clientY);zipDrag.x=e.clientX;zipDrag.y=e.clientY});"""
new="""/* Zip live drag fix v4 */
function zipCellFromPoint(clientX,clientY){const r=zipStage.getBoundingClientRect();if(clientX<r.left||clientX>r.right||clientY<r.top||clientY>r.bottom)return null;const x=Math.max(0,Math.min(zipCols-1,Math.floor((clientX-r.left)/r.width*zipCols))),y=Math.max(0,Math.min(zipRows-1,Math.floor((clientY-r.top)/r.height*zipRows)));return{x,y}}
function zipUpdateLiveUI(){const used=new Set(zipPathCells.map(([x,y])=>zipKey(x,y)));zipStage.querySelectorAll('.zip-cell').forEach(c=>{const x=+c.dataset.x,y=+c.dataset.y,key=zipKey(x,y),isCurrent=zipPathCells.length&&zipPathCells.at(-1)[0]===x&&zipPathCells.at(-1)[1]===y;c.classList.toggle('used',used.has(key));c.classList.toggle('current',!!isCurrent)});drawZipPath();const nextAnchor=[...zipAnchors.entries()].find(([idx,n])=>idx>=zipPathCells.length);$('zipMessage').textContent=zipPathCells.length===zipSolution.length?'Complete — every box used.':zipPathCells.length?'Keep filling every box · next number '+(nextAnchor?nextAnchor[1]:'✓'):'Start at 1 · use every box.'}
function zipTryCellLive(x,y){if(!zipPathCells.length){const first=zipSolution[0];if(x!==first[0]||y!==first[1])return false}else{const [px,py]=zipPathCells.at(-1),dx=Math.abs(x-px),dy=Math.abs(y-py);if(dx+dy!==1)return false;const prevIndex=zipPathCells.findIndex(p=>p[0]===x&&p[1]===y);if(prevIndex===zipPathCells.length-2){zipPathCells.pop();zipUpdateLiveUI();return true}if(prevIndex>=0)return false;const anchor=zipExpectedAnchorAtCell(x,y),next=zipNextAnchorNumber();if(anchor&&anchor!==next)return false}zipPathCells.push([x,y]);beep(360+Math.min(300,zipPathCells.length*5),.025);zipUpdateLiveUI();if(zipPathCells.length===zipSolution.length){const exact=zipPathCells.every((p,i)=>p[0]===zipSolution[i][0]&&p[1]===zipSolution[i][1]);if(exact){toast('Every box connected ✦');setTimeout(()=>{zipLevel++;makeZip();renderZip()},850)}else toast('Almost — check the number order')}return true}
function zipProcessDrag(x1,y1,x2,y2){const r=zipStage.getBoundingClientRect(),cell=Math.min(r.width/zipCols,r.height/zipRows),dist=Math.hypot(x2-x1,y2-y1),steps=Math.max(1,Math.ceil(dist/Math.max(4,cell*.18)));let last='';for(let i=1;i<=steps;i++){const t=i/steps,c=zipCellFromPoint(x1+(x2-x1)*t,y1+(y2-y1)*t);if(!c)continue;const key=c.x+','+c.y;if(key===last)continue;last=key;zipTryCellLive(c.x,c.y)}}
const zipStage=$('zipStage');zipStage.addEventListener('pointerdown',e=>{const el=e.target.closest?.('.zip-cell');if(!el)return;e.preventDefault();const x=+el.dataset.x,y=+el.dataset.y;if(!zipPathCells.length&&el.textContent.trim()!=='1')return;if(!zipTryCellLive(x,y))return;zipDrag={id:e.pointerId,x:e.clientX,y:e.clientY};try{zipStage.setPointerCapture(e.pointerId)}catch{}});zipStage.addEventListener('pointermove',e=>{if(!zipDrag||zipDrag.id!==e.pointerId)return;e.preventDefault();zipProcessDrag(zipDrag.x,zipDrag.y,e.clientX,e.clientY);zipDrag.x=e.clientX;zipDrag.y=e.clientY});"""
if old not in s:
    raise SystemExit('zip v3 block not found')
s=s.replace(old,new,1)
p.write_text(s)
print('patched zip live drag')
